source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    markers = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != background}
    for r in range(h):
        cols = [c for rr, c in markers if rr == r]
        if len(cols) >= 2:
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == background:
                    out[r][c] = 3
    for c in range(w):
        rows = [r for r, cc in markers if cc == c]
        if len(rows) >= 2:
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == background:
                    out[r][c] = 3
    return out
'''
